# Applied last so guide and JEI explanations share the current physical assembly rules.
function Machine-ComponentTranslations {
    $t=[ordered]@{
        'machine.alone_mechanical.forging_press'=@('锻压机','Forging Press')
        'message.alone_mechanical.requires_forging_component'=@('工业核心需要上方机型组件；核反应堆需要同高四周紧贴燃料棒','Industrial core needs a component above, or four adjacent horizontal fuel rods for a nuclear reactor')
        'machine.alone_mechanical.forming_machine'=@('塑形机','Forming Machine')
        'machine.alone_mechanical.infuser'=@('灌注机','Infuser')
        'message.alone_mechanical.requires_forming_stores'=@('塑形机需要恰好两列独立物品仓：输入1、输出1；不能使用其他通道或储罐','Forming needs exactly two independent item vault columns: Input 1 and Output 1; no other channels or tanks')
        'message.alone_mechanical.requires_infuser_stores'=@('灌注机需要恰好三列独立仓储：输入1物品仓、输入2流体或气体罐、输出1物品仓','Infusion needs exactly three independent columns: item Input 1, fluid OR gas Input 2, item Output 1')
        'jei.alone_mechanical.forming_machine'=@('工业核心正上方紧贴塑形组件。输入1、输出1各一列独立物品仓；完整外壳、唯一控制器、至少一个能量矩阵。执行独立物品→物品塑形配方，目前无默认案例。','Place a forming component directly above an industrial core. Separate item Input 1/Output 1 columns, complete casing, one controller and an energy matrix. Uses independent item-to-item forming recipes; none ship by default.')
        'jei.alone_mechanical.infuser'=@('工业核心正上方紧贴灌注组件。恰好三列：输入1物品仓、输入2流体或气体罐、输出1物品仓。辅料只能为一种流体或气体，使用独立灌注配方；已有14条维度转换配方，每份250 mB、100 tick、40 FE/t，花朵/藤蔓产物各50%。','Place an infusion component directly above an industrial core. Exactly three columns: item Input 1, fluid OR gas Input 2, item Output 1. Each recipe uses one fluid or gas additive. Includes 14 dimension recipes at 250 mB, 100 ticks and 40 FE/t each; flowers/vines have two exclusive 50% outcomes.')
        'message.alone_mechanical.requires_smelting_component'=@('熔炼核心正上方必须紧贴煅烧组件（电弧炉）或合金组件（合金冶炼机）','Place a calcination component (arc furnace) or alloy component (alloy smelter) directly above the smelting core')
        'message.alone_mechanical.requires_reaction_component'=@('反应核心正上方必须紧贴化合组件（反应釜）或分解组件（分离机）','Place a combination component (reactor) or decomposition component (separator) directly above the reaction core')
        'message.alone_mechanical.unexpected_machine_component'=@('该核心不支持正上方的机型组件','This core does not support the machine component above it')
        'message.alone_mechanical.misplaced_machine_component'=@('机型组件只能放一个，且必须紧贴中心核心正上方','Use exactly one machine component, directly above the center core')
        'message.alone_mechanical.obsolete_machine_core'=@('旧合金/分离核心已停用：改用熔炼核心+合金组件，或反应核心+分解组件','Legacy alloy/separation cores cannot form: use smelting core + alloy component, or reaction core + decomposition component')
        'jei.alone_mechanical.forging_press'=@('工业核心放在选区内部中心，正上方紧贴锻压组件。至少两个独立物品仓列，输入1、输出1各27槽，端口接仓列上/下端；完整外壳、一个控制器、至少一个能量矩阵。使用alone_mechanical:forging_press独立加工配方，当前没有默认锻压配方。','Place an industrial core at the interior center with a forging component directly above. Use separate item Input 1/Output 1 vault columns with at least 27 slots each, attached top/bottom ports, complete casing, one controller and an energy matrix. Uses independent alone_mechanical:forging_press recipes; none ship by default.')
        'jei.alone_mechanical.alloy_smelter'=@('熔炼核心正上方紧贴合金组件。恰好三列：输入1物品主料、输入2物品/流体/气体辅料、输出1物品。完整外壳、一个控制器、至少一个能量矩阵。2铁粉+1碳粉→2钢锭，200 tick，40 FE/t。','Place an alloy component directly above a smelting core. Exactly three columns: item Input 1, item/fluid/gas Input 2 and item Output 1. Complete casing, one controller and an energy matrix. 2 iron dust + 1 carbon dust → 2 steel ingots, 200 ticks at 40 FE/t.')
        'jei.alone_mechanical.smelting'=@('熔炼核心正上方紧贴煅烧组件构成电弧炉；以FE加工当前已加载的熔炼配方。','A calcination component directly above the smelting core forms an arc furnace, which uses FE for loaded furnace recipes.')
    }
    $base=Tutorial-Translations
    $separator=Separator-Translations
    $t['tutorial.alone_mechanical.structure.body']=@(
        ($base['tutorial.alone_mechanical.structure.body'][0]+"`n`n机型组件必须紧贴核心正上方且只能有一个：工业+锻压→锻压机；熔炼+煅烧→电弧炉；熔炼+合金→合金机；反应+化合→反应釜；反应+分解→分离机。粉碎核心与转化核心仍直接识别。旧合金核心/分离核心不能构建。"),
        ($base['tutorial.alone_mechanical.structure.body'][1]+"`n`nUse exactly one component directly above the core: industrial + forging → forging press; smelting + calcination → arc furnace; smelting + alloy → alloy smelter; reaction + combination → reactor; reaction + decomposition → separator. Crusher/conversion cores still work directly. Legacy alloy/separation cores cannot form."))
    $t['tutorial.alone_mechanical.machines.body']=@(
        ($base['tutorial.alone_mechanical.machines.body'][0].Replace('电弧炉：熔炼核心，','电弧炉：熔炼核心正上方紧贴煅烧组件，').Replace('合金冶炼机：合金核心，','合金冶炼机：熔炼核心正上方紧贴合金组件，')+"`n`n锻压机：工业核心正上方紧贴锻压组件。至少两列独立物品仓，输入1/输出1各27槽；其余外壳、控制器、能量矩阵及端口规则与粉碎机相同。当前没有默认锻压配方，数据包使用machine=alone_mechanical:forging_press注册。"),
        ($base['tutorial.alone_mechanical.machines.body'][1].Replace('Arc furnace: smelting core','Arc furnace: smelting core with a calcination component directly above').Replace('Alloy smelter: alloy core','Alloy smelter: smelting core with an alloy component directly above')+"`n`nForging press: industrial core with a forging component directly above. Separate Input 1/Output 1 vault columns need 27 slots each; other shell/controller/matrix/port rules match the crusher. No default forging recipes; data packs use machine=alone_mechanical:forging_press."))
    $t['tutorial.alone_mechanical.reactors.body']=@($base['tutorial.alone_mechanical.reactors.body'][0].Replace('反应核心，','反应核心正上方紧贴化合组件，'),$base['tutorial.alone_mechanical.reactors.body'][1].Replace('Use a reaction core and','Use a reaction core with a combination component directly above, and'))
    $t['tutorial.alone_mechanical.separation.body']=@(
        ($separator['tutorial.alone_mechanical.separation.body'][0].Replace('分离核心','反应核心（正上方紧贴分解组件）')+"`n`n同介质分解：物品分解=物品→物品+物品；流体分解=流体→流体+流体；气体分解=气体→气体+气体。三者均为输入1、输出1、输出2独立三列；使用独立配方，不会自动反推化合配方。"),
        ($separator['tutorial.alone_mechanical.separation.body'][1].Replace('separation core','reaction core with a decomposition component directly above')+"`n`nSame-phase decomposition: item → item + item; fluid → fluid + fluid; gas → gas + gas. Each uses independent Input 1, Output 1 and Output 2 columns and recipes, never automatically reversed reaction recipes."))
    $t['jei.alone_mechanical.separator']=@($separator['jei.alone_mechanical.separator'][0].Replace('分离核心','反应核心（正上方紧贴分解组件）'),$separator['jei.alone_mechanical.separator'][1].Replace('separation core','reaction core with a decomposition component directly above'))
    $t['jei.alone_mechanical.biphasic_reactor']=@('中心反应核心正上方紧贴化合组件；输入1、输入2、输出1各一列独立仓储。介质选择九种模式，使用对应独立配方。','Place a combination component directly above the reaction core; separate Input 1, Input 2 and Output 1 columns select nine profiles with independent recipes.')
    $t['tutorial.alone_mechanical.structure.body'][0]+="`n`n工业核心还支持：正上方放塑形组件→塑形机；放灌注组件→灌注机。"
    $t['tutorial.alone_mechanical.structure.body'][1]+="`n`nIndustrial cores also support forming and infusion components directly above them, selecting a forming machine or infuser."
    $t['tutorial.alone_mechanical.machines.body'][0]+="`n`n塑形机：工业核心+正上方塑形组件。恰好输入1、输出1两列物品仓，物品→物品；目前无默认塑形案例。`n`n灌注机：工业核心+正上方灌注组件。恰好输入1物品仓、输入2流体或气体罐、输出1物品仓。物品+一种流体/气体→物品，禁止物品辅料或同时使用两种介质；现有14条维度转换灌注配方，每份250 mB、100 tick、40 FE/t；花朵和藤蔓各随机获得一种地狱产物，概率各50%。两种机器均须满足通用外壳、控制器、能量矩阵与上下端口规则，使用各自独立配方。"
    $t['tutorial.alone_mechanical.machines.body'][1]+="`n`nForming machine: industrial core + forming component above. Exactly two item columns: Input 1 and Output 1. Item-to-item processing; no default examples. `n`nInfuser: industrial core + infusion component above. Exactly three columns: item Input 1, fluid OR gas Input 2, item Output 1. One resource additive only; item additives and simultaneous fluid+gas inputs are rejected. Includes 14 dimension infusion recipes at 250 mB, 100 ticks and 40 FE/t per item; flowers and vines yield one of two Nether products at 50% each. Both follow common casing/controller/energy-matrix/top-bottom-port rules and use independent recipes."
    return $t
}
